 core:hasLocation [
 core:hasAddress [
 core:hasCity ?city
 ]
 ]
 ]
 ] .
 }
 UNION
 { #same builder (stated name)
 ?organ_query_iri core:describedBy [
 a organ:OrganProject ;
 core:definesTask [
 rdf:type core:Task ;
 core:isClassifiedBy organ:TaskTypeBuild
 ] ;
 core:hasProjectist [
 core:hasRole organ:Builder ;
 core:involvesAgent [
 core:hasName [
 core:name ?builder_name
 ]
 ]
 ]
 ] .

 ?organ_iri rdfs:label ?label ;
 core:describedBy [
 a organ:OrganProject ;
 core:definesTask [
 rdf:type core:Task ;
 core:isClassifiedBy organ:TaskTypeBuild
 ] ;
 core:hasProjectist [
 core:hasRole organ:Builder ;
 core:involvesAgent [
 core:hasName [
 core:name ?builder_name
 ]
 ]
 ]
 ] . 
 }
 UNION { #same builder (disambiguated name)
 ?organ_query_iri core:describedBy [
 a organ:OrganProject ;
 core:definesTask [
 rdf:type core:Task ;
 core:isClassifiedBy organ:TaskTypeBuild
 ] ;
 core:hasProjectist [
 core:hasRole organ:Builder ;
 core:involvesAgent [
 core:hasName ?disamb_builder_name
 ]
 ]
 ] .

 ?disamb_builder_name a core:DisambiguatedName .

 ?organ_iri rdfs:label ?label ;
 core:describedBy [
 a organ:OrganProject ;
 core:definesTask [
 rdf:type core:Task ;
 core:isClassifiedBy organ:TaskTypeBuild
 ] ;
 core:hasProjectist [
 core:hasRole organ:Builder ;
 core:involvesAgent [
 core:hasName ?disamb_builder_name
 ]
 ]
 ] . 
 }

